/*
 * UI strings in pl, en, de, fr (en is the fallback). Pure data: no DOM, no React.
 * ⛔ No string anywhere says or implies that data is "ready to publish" — the tool only reports what it
 * did not find in the categories it checked (test/app/ui.test.ts enforces the four phrasings).
 * Placeholders are {name}; every language must use the same set for a key.
 * The list of allowlisted data hosts on the privacy page is rendered by the page from config/hosts.ts.
 */
