  'convert.sheet.profile.depthIds': `Make the level IDs from the station and the depth as written`,
  'convert.sheet.profile.depthIds.help': `This sheet has no code column (bottle, scan or Niskin number). With this tick, the ID of a level is the station's eventID, a colon and the depth as written in the sheet (a decimal comma becomes a point) with m after it; a row without a readable depth takes its pressure, with dbar after it, when the pressure column is in decibars. Without the tick, the rows are blocked until a code column is mapped as the sample code. Two rows of a station at the same depth or pressure (repeated casts) make the same ID and block the export. A station with rows of more than one date has the date in the ID too (station, date, depth).`,
  'convert.sheet.profile.cast': `Match the stations ignoring a trailing cast number (-N)`,
  'convert.sheet.profile.cast.help': `Event labels of PANGAEA end with the cast of each device ("PS27/006-6" for a net, "PS27/006-1" for a CTD). With this tick, a station of this sheet is matched to the biology station whose text is the same apart from that ending; the level then sits under that station. A base that more than one biology station has is not matched. Without the tick only an identical text matches.`,
  'convert.sheet.profile.position': `Each distinct position is a station`,
  'convert.sheet.profile.position.help': `This sheet has no station column. With this tick, every distinct pair of latitude and longitude, as written in the sheet, is one station; its ID is the cruise code, a colon, the latitude, an underscore and the longitude. A row with no readable position then has no station and is blocked. Without the tick, the rows are blocked until a column is mapped as the station.`,
  'convert.sheet.profile.stations.title': `Matching the stations`,
  'convert.sheet.profile.stations': `The stations of this sheet are matched to the stations of the biology sheets by their exact text and the cruise, when there is one. A station with no match becomes a station of its own, and the export asks you to accept that.`,
  'convert.sheet.profile.pressure.title': `Pressure`,
  'convert.sheet.profile.pressure': `A pressure column is written as a measurement of each level. Where the sheet has no depth column, the depth stays empty: a pressure is not turned into a depth in this version.`,
  'convert.options.title': `Choices for the whole upload`,
  'convert.fullList': `This is a full species list`,
  'convert.fullList.help': `Tick it only if every species of the list was looked for in every sample. Then a zero means absent; without the tick zeros are left out.`,
  'convert.worms.title': `Species names in WoRMS (optional)`,
  'convert.worms.optin': `Match the taxon names to WoRMS`,
  'convert.worms.optin.help': `Off by default. Ticking the box sends nothing: the names leave your computer only when you press the lookup button.`,
  'convert.worms.privacy.title': `What is sent, and to whom`,
  'convert.worms.privacy.sent': `What is sent: only the taxon names (the scientific name without qualifier, stage or sex). Never values, codes, station names, file names, descriptions or anything you typed.`,
  'convert.worms.privacy.to': `To whom: WoRMS, the World Register of Marine Species, operated by VLIZ (the Flanders Marine Institute), at www.marinespecies.org. The names go from your browser straight to that service, not through this site's server.`,
  'convert.worms.privacy.ip': `The service sees your IP address, as any website you open does.`,
  'convert.worms.privacy.unpublished': `Species names can reveal unpublished findings (which species were found in your data). If that matters, leave this off.`,
  'convert.worms.privacy.button': `Nothing is sent until you press the lookup button. Without that press nothing leaves your computer, even when the box is ticked or a companion file ticked it.`,
  'convert.worms.names.summary': `Names that would be sent ({n})`,
  'convert.worms.skipped': `Names that have an ID from a column of your sheet on at least one row are not sent, and none of their rows gets a WoRMS ID (count: {n}).`,
  'convert.worms.none': `There are no names to look up yet. Names appear here once the sheet converts and its name splits are approved; names that already have an ID from the sheet are left out.`,
  'convert.worms.lookup': `Look up {n} {+n:name|names} in WoRMS`,
