  'convert.nerc.title': `NERC concepts for measured variables`,
  'convert.nerc.intro': `Each measured-variable column is written as one measurement on every sample event (on every profile level, for a profile file), with its name and its unit as in the column table above. For a column whose concept you confirm, the name is written as the English name of that concept (its preferred label in the NERC vocabulary). An identifier from the NERC Vocabulary Server (measurementTypeID for the quantity, measurementUnitID for the unit) is written only for what you confirm here, column by column. A suggestion is shown, never selected for you.`,
  'convert.nerc.col.unit': `unit`,
