  'convert.nerc.group.offered': `Offered (names a method, a phase or a narrower quantity)`,
  'convert.nerc.group.nvs': `Results of your NVS search`,
  'convert.nerc.group.declared': `Declared by the file (the tool could not check it)`,
  'convert.nerc.declared.label': `declared in the header, not checked`,
  'convert.nerc.deprecated': `deprecated, cannot be chosen`,
  'convert.nerc.dropped': `The earlier choice was dropped: the variable or the unit of this column changed, and an identifier belongs to both.`,
  'convert.nerc.useSuggested': `Use the suggestions for {n} {+n:column|columns}`,
  'convert.nerc.useSuggested.help': `Confirms, for the columns that have no choice yet, the suggested concept and unit shown in their lists. You can change any of them afterwards.`,
  'convert.nerc.choose.intro': `For each column, choose the concept and the unit, or leave "No ID": an identifier you did not choose is not written, and the summary says which variables and units are left without one.`,
