  'collection.duplicates': `{n} {+n:repeat was|repeats were} counted once: the same DOI more than once in the pasted list, or the same Zenodo record in more than one date slice.`,
  'collection.checks.title': `What this page does`,
  'collection.checks.p1': `It reads metadata records, never data files, and applies the licence and metadata rules of the other tools to each record it could read:`,
  'collection.checks.li1': `a missing, free-text or unrecognised licence statement, and a licence given in the text that differs from its link;`,
