  'collection.checks.li3': `empty links, a missing version and a missing spatial extent in the metadata.`,
  'collection.checks.li4': `A record that cannot be read (unreachable, held back by the source, or in an unsupported profile) is listed as not read and gets no finding. Nothing is ranked and no institutions are compared.`,
