  'licence.reason.notRead': `This kind of link is not read for licences. Paste the dataset's DOI instead, to compare what its DataCite record states.`,
  'licence.reason.notReadObis': `This kind of link is not read for licences. OBIS datasets have no DOI of their own: if the same dataset is also published through GBIF or the data provider's IPT and has a DOI there, paste that DOI instead, to compare what its DataCite record states.`,
