  'licence.summary.none': `No contradiction among {n} sources that state a recognised licence`,
  'licence.summary.noneMaybeSame': `No contradiction among {n} records — but these are Zenodo DOIs that may be versions of one deposit (this could not be confirmed because the Zenodo record was not read), so one source may be counted twice`,
