  'licence.summary.dataciteSilent.where': `Stated by {where}.`,
  'licence.summary.dataciteSilent.unread': `No source that was read states a licence, and at least one could not be read, so no licence was found.`,
  'licence.summary.dataciteSilent.openaire': `The OpenAIRE guidelines for data archives make Rights (the licence) mandatory when applicable, where DataCite leaves it optional: add the licence to the DOI record.`,
  'licence.summary.uncompared': `Statements found, but none could be read as a licence this tool recognises — nothing was compared`,
  'licence.summary.partial': `Only one source gives a licence this tool recognises; the other statements could not be compared`,
  'licence.summary.contradictions': `Contradictions found: {n}`,
  'licence.summary.countOnce': `Sources of one deposit count once.`,
  'licence.summary.unreadable': `At least one source could not be read; it is not part of this comparison.`,
  'licence.summary.unrecognised': `Statements marked "unrecognised" cannot be compared; check them manually.`,
  'licence.attr.title': `Attribution text`,
  'licence.attr.note': `The attribution text is always in English, so that you can paste it as it is. Check it against the record before you use it.`,
  'licence.attr.copy': `Copy`,
  'licence.attr.copied': `Copied to the clipboard.`,
  'licence.attr.copyFailed': `Copying did not work here; select the text and copy it by hand.`,
  'licence.attr.empty': `The sources do not hold enough to build an attribution text.`,
  'licence.attr.omit.none': `The licence is left out: no source states a licence that this page recognises.`,
  'licence.attr.omit.unreadable': `The licence is left out: at least one source could not be read, and none that was read states a licence this page recognises.`,
  'licence.attr.omit.several': `The licence is left out: more than one licence is recognised across the sources.`,
  'licence.attr.omit.contradiction': `The licence is left out: the sources contradict each other.`,
  'licence.attr.omit.unrecognised': `The licence is left out: at least one statement is unrecognised and needs a manual check.`,
  'licence.checks.title': `What this checks`,
  'licence.checks.p1': `This page reads the metadata of the records you reference, never the data files. It reads the licence statements in Zenodo records, PANGAEA metadata records, Dataverse datasets (RepOD), GeoNetwork records (ISO 19139 and ISO 19115-3) and the DataCite record of a DOI.`,
  'licence.checks.li1': `Each statement is classified by comparing its text and its link with the SPDX licence list: one SPDX identifier, or "unrecognised — check manually".`,
  'licence.checks.li2': `Sources are compared by the identifiers they state. A Zenodo record and its DataCite record, a PANGAEA record and its DataCite record, or a Dataverse dataset and its DataCite record, are one deposit and count once.`,
  'licence.checks.li3': `Contradictions it reports: different licences in different sources, text and link that disagree, a text that adds conditions to a standard licence, and access restrictions in an ISO record next to an open licence. An empty DataCite record next to a licence stated elsewhere is not a contradiction: it has a line of its own.`,
  'licence.checks.li4': `It does not interpret the legal effect of a licence, does not read licence texts and does not look at the data itself.`,
