  'convert.meta.f.basis': `Rodzaj zapisu (basisOfRecord)`,
  'convert.meta.licence.help': `Licencję wybiera posiadacz praw do danych, nie to narzędzie. OBIS przyjmuje te trzy; licencji Creative Commons z ShareAlike (SA) lub NoDerivatives (ND) nie ma na jego liście, więc nie są oferowane.`,
  'convert.meta.licence.CC0-1.0': `CC0 1.0 (domena publiczna; preferowana przez OBIS)`,
