  'convert.accept.title': `Ostrzeżenia do zaakceptowania`,
  'convert.accept.intro': `Te ostrzeżenia nie blokują eksportu, ale archiwum będzie zawierać to, o czym mówią. Zaznacz każdy rodzaj po przeczytaniu. Zaznaczenie trwa, dopóki uwagi tego rodzaju się nie zmienią; gdy się zmienią, trzeba je dać ponownie. Po opuszczeniu strony nic nie jest zapamiętywane.`,
  'convert.accept.rule': `Akceptuję {n} {+n:ostrzeżenie|ostrzeżenia|ostrzeżeń} tego rodzaju ({rule})`,
  'convert.accept.unconfirmed': `Akceptuję pominięcie niepotwierdzonych kolumn taksonów: {n}`,
  'convert.export.title': `Eksport`,
  'convert.export.button': `Pobierz archiwum Darwin Core`,
  'convert.export.blocked': `Eksport jest wyłączony: napraw to, co go blokuje, uzupełnij opis i zaakceptuj każde ostrzeżenie.`,
  'convert.export.empty': `Nie ma jeszcze czego eksportować: nie zapisano by żadnego zdarzenia lub wystąpienia.`,
  'convert.export.working': `Budowanie archiwum…`,
  'convert.export.files': `Zip zawiera meta.xml, eml.xml, event.txt, occurrence.txt oraz, gdy są pomiary, extendedmeasurementorfact.txt.`,
  'convert.export.done': `Pobrano {name}: {events} {+events:zdarzenie|zdarzenia|zdarzeń}, {occurrences} {+occurrences:wystąpienie|wystąpienia|wystąpień} i {measurements} {+measurements:wiersz|wiersze|wierszy} pomiarów.`,
  'convert.export.stored': `Ta przeglądarka nie umie kompresować, więc archiwum zapisano bez kompresji: jest większe, ale poprawne.`,
  'convert.companion.button': `Pobierz plik towarzyszący`,
  'convert.companion.help': `Zachowuje Twoje wybory (pełna lista gatunków, przedrostek stacji, opcja WoRMS, opcja NVS) na następny raz: wgraj go razem z danymi.`,
  'convert.doubt.sex-marker': `na końcu zostało oznaczenie płci`,
  'convert.taxa.label': `Zaproponowane kolumny taksonów`,
  'convert.medium.none': `— wybierz —`,
  'convert.sex.none': `—`,
  'convert.taxa.title': `Kolumny zaproponowane jako taksony: {n}`,
  'convert.taxa.intro': `Narzędzie zaproponowało te kolumny, bo zawierają liczby pod nazwą, której nie zna, a nie dlatego, że rozpoznało gatunek. Kolumna jest przekształcana dopiero po Twoim potwierdzeniu; odznacz każdą, która nie jest taksonem.`,
  'convert.taxa.confirmAll': `Potwierdź wszystkie pokazane ({n})`,
  'convert.taxa.confirm': `Potwierdź jako takson: {header}`,
  'convert.taxa.unconfirmed': `Niepotwierdzone kolumny taksonów: {n}. Nie są przekształcane.`,
  'convert.splits.doubt': `Sprawdź nazwę: {reason}`,
  'convert.doubt.digits': `zawiera cyfrę`,
  'convert.doubt.slash': `zawiera ukośnik (dwie nazwy?)`,
  'convert.doubt.question': `zawiera znak zapytania`,
  'convert.doubt.stage-range': `wygląda na zakres stadiów`,
  'convert.doubt.single-letter': `zawiera pojedynczą literę`,
  'convert.doubt.long': `ma więcej niż trzy słowa`,
  'convert.doubt.remark': `po przecinku zostało dopowiedzenie, które nie jest stadium, dopiskiem ani płcią`,
