  'convert.worms.choose.intro': `Dla każdej nazwy poniżej wybierz, który wynik stanie się jej identyfikatorem. Automatycznie przyjmowane jest tylko pojedyncze dokładne dopasowanie. Przy każdym wyniku tabela mówi, jak zapisano by scientificName.`,
