  'convert.worms.writtenAs': `Jeśli to wybierzesz: scientificName zostanie zapisana jako „{name}”; Twoja pisownia zostanie w verbatimIdentification.`,
  'convert.worms.writtenSame': `Jeśli to wybierzesz: scientificName zostanie taka, jak w Twoim arkuszu.`,
  'convert.nerc.title': `Pojęcia NERC dla mierzonych wielkości`,
  'convert.nerc.intro': `Każda kolumna ze zmierzoną wielkością jest zapisywana jako jeden pomiar przy każdym zdarzeniu próbki (w pliku profilowym przy każdym poziomie profilu), z nazwą i jednostką z tabeli kolumn powyżej. Dla kolumny, której pojęcie potwierdzisz, nazwa jest zapisywana jako angielska nazwa tego pojęcia (jego preferowana etykieta w słowniku NERC). Identyfikator ze słownika NERC (measurementTypeID dla wielkości, measurementUnitID dla jednostki) jest zapisywany tylko dla tego, co tu potwierdzisz, kolumna po kolumnie. Podpowiedź jest pokazana, ale nigdy nie jest wybrana za Ciebie.`,
  'convert.nerc.col.unit': `jednostka`,
