  'convert.nerc.dropped': `Poprzedni wybór został odrzucony: zmieniła się wielkość lub jednostka tej kolumny, a identyfikator należy do obu.`,
  'convert.nerc.useSuggested': `Użyj podpowiedzi dla {n} {+n:kolumny|kolumn|kolumn}`,
  'convert.nerc.useSuggested.help': `Potwierdza, dla kolumn bez wyboru, podpowiedziane pojęcie i jednostkę z ich list. Każdą z nich możesz potem zmienić.`,
  'convert.nerc.choose.intro': `Dla każdej kolumny wybierz pojęcie i jednostkę albo zostaw „Bez identyfikatora”: identyfikator, którego nie wybrano, nie jest zapisywany, a podsumowanie mówi, którym wielkościom i jednostkom go brakuje.`,
  'convert.nerc.choose.label': `Wybór pojęcia i jednostki`,
  'convert.nvs.title': `Szukaj w serwerze słownika NERC (opcjonalnie)`,
  'convert.nvs.optin': `Zezwól na szukanie pojęcia lub jednostki w NVS`,
  'convert.nvs.optin.help': `Domyślnie wyłączone. Samo zaznaczenie niczego nie wysyła: słowo opuszcza Twój komputer dopiero, gdy wpiszesz je dla kolumny i naciśniesz „Szukaj w NVS”.`,
  'convert.nvs.privacy.title': `Co jest wysyłane i do kogo`,
  'convert.nvs.privacy.sent': `Co jest wysyłane: wyłącznie wpisane przez Ciebie słowo wyszukiwania i nic więcej. Nigdy dane, wartości, nazwy kolumn, nazwy plików, opisy ani nic innego, co wpisano.`,
  'convert.nvs.privacy.to': `Do kogo: do serwera słownika NERC (NVS), prowadzonego przez British Oceanographic Data Centre (BODC, brytyjskie centrum danych oceanograficznych) w National Oceanography Centre (NOC), pod adresem vocab.nerc.ac.uk. Słowo idzie z Twojej przeglądarki prosto do tej usługi, nie przez serwer tej strony.`,
  'convert.nvs.privacy.ip': `Usługa widzi Twój adres IP, jak każda otwierana strona.`,
  'convert.nvs.privacy.button': `Nic nie jest wysyłane, zanim nie naciśniesz „Szukaj w NVS”. Bez tego nic nie opuszcza Twojego komputera, nawet gdy pole jest zaznaczone albo zaznaczył je plik towarzyszący.`,
