  'convert.prefix': `Poprzedź każdy kod próbki kodem jej stacji`,
  'convert.prefix.help': `Niektóre kody próbek powtarzają się między stacjami, więc nie mogą być identyfikatorami w tej postaci. Identyfikator stacji, dwukropek i Twój kod czynią je unikalnymi.`,
  'convert.splits.title': `Nazwy z dopiskiem, stadium lub płcią`,
  'convert.splits.intro': `Każda poniższa nazwa została podzielona na nazwę naukową i to, co z niej wyjęto, albo pozostała nazwa wygląda wątpliwie. Dokładny tekst zawsze zostaje. Popraw pola, jeśli propozycja jest błędna, potem zatwierdź każdą z osobna. Przycisk dla wszystkich pokazanych zatwierdza tylko nazwy bez wątpliwości; nazwa z wątpliwością ma własny przycisk, po poprawieniu albo przyjęciu jej bez zmian. Niezatwierdzona blokuje przekształcenie.`,
