  'convert.codes.title': `Kody próbek`,
  'convert.codes.text': `Arkusz {sheet} z pliku {file} ma wiersze bez kodu próbki. Kod staje się identyfikatorem próbki w archiwum, więc musi pochodzić od Ciebie, a konwerter nigdy po cichu go nie wymyśla. Może raz zaproponować kody: pobierasz własny arkusz z jedną nową kolumną, sprawdzasz kody i wgrywasz ten plik ponownie.`,
