  'collection.title': `Przegląd kolekcji`,
  'collection.docTitle': `Przegląd kolekcji: znajdź problemy z licencjami i metadanymi w całym repozytorium`,
  'collection.intro': `Przeczytaj metadane całej kolekcji i otrzymaj liczby według problemów, kilka przykładów każdego oraz listę poprawek w pliku CSV. Czytane są tylko metadane, nigdy pliki z danymi. Szybka próba jest zawsze oznaczona jako próba; nic tu nie tworzy rankingów ani nie porównuje instytucji.`,
