  'collection.dois.label': `Numery DOI, po jednym w wierszu lub oddzielone spacjami`,
  'collection.dois.placeholder': `10.5281/zenodo.…
https://doi.org/10.…`,
  'collection.dois.hint': `Każdy numer DOI jest wyszukiwany w DataCite przez Twoją przeglądarkę. Akceptowane są linki doi.org/… oraz zapis doi:…; powtórzone numery są czytane raz.`,
  'collection.dc.by': `Kolekcję wskazuje`,
  'collection.dc.client': `identyfikator klienta DataCite (repozytorium)`,
  'collection.dc.prefix': `prefiks DOI`,
  'collection.dc.label': `Identyfikator klienta lub prefiks`,
  'collection.dc.hint': `Twoja przeglądarka pobiera listę z DataCite stronami. Identyfikator klienta ma postać „organizacja.repozytorium”, prefiks — „10.1234”.`,
  'collection.zen.label': `Nazwa społeczności (jak w jej adresie w Zenodo)`,
  'collection.zen.hint': `Zenodo pozwala gościowi czytać 25 rekordów na zapytanie i 30 zapytań na minutę, więc duże społeczności zajmują dużo czasu. Społeczności liczące ponad 10 000 rekordów są czytane we fragmentach podzielonych według daty publikacji.`,
  'collection.csw.label': `Katalog`,
  'collection.csw.schema': `Żądany format metadanych`,
  'collection.csw.note': `Katalogi są czytane przez nasz serwer, który przekazuje odpowiedź dalej i niczego nie przechowuje (zob. stronę o prywatności). Można czytać tylko katalogi z tej listy.`,
  'collection.csw.cross': `Porównaj też z DataCite`,
  'collection.csw.cross.note': `Dla rekordów, które podają numer DOI, Twoja przeglądarka sprawdza też ten numer w DataCite i porównuje licencje obu źródeł. Daje to do jednego dodatkowego zapytania na taki rekord.`,
