  'collection.estimate.extra': `Plus do {n} {+n:zapytania|zapytań|zapytań} do DataCite na potrzeby porównania.`,
  'collection.estimate.approx': `Liczba zapytań jest tylko przybliżona.`,
  'collection.estimate.slices': `Ta społeczność jest czytana w co najmniej około {slices} fragmentach podzielonych według daty publikacji, liczonych w trakcie przebiegu.`,
  'collection.estimate.sampleFirst': `To bardzo duża społeczność: pełny przebieg trwa długo. Zacznij od szybkiej próby (około minuty); obejmuje tylko część kolekcji. Pełny przebieg uruchom, gdy chcesz przeczytać wszystko.`,
