  'licence.attr.copyFailed': `Kopiowanie tu nie zadziałało; zaznacz tekst i skopiuj go ręcznie.`,
  'licence.attr.empty': `Źródła nie zawierają dość, by zbudować tekst atrybucji.`,
  'licence.attr.omit.none': `Licencja pominięta: żadne źródło nie podaje licencji rozpoznanej przez tę stronę.`,
  'licence.attr.omit.unreadable': `Licencja pominięta: co najmniej jednego źródła nie udało się odczytać, a żadne z odczytanych nie podaje licencji rozpoznanej przez tę stronę.`,
  'licence.attr.omit.several': `Licencja pominięta: w źródłach rozpoznano więcej niż jedną licencję.`,
  'licence.attr.omit.contradiction': `Licencja pominięta: źródła sobie przeczą.`,
  'licence.attr.omit.unrecognised': `Licencja pominięta: co najmniej jedno stwierdzenie jest nierozpoznane i wymaga ręcznego sprawdzenia.`,
  'licence.checks.title': `Co to sprawdza`,
  'licence.checks.p1': `Strona czyta metadane rekordów, do których się odwołujesz, nigdy pliki z danymi. Czyta stwierdzenia o licencji w rekordach Zenodo, rekordach metadanych PANGAEA, zbiorach Dataverse (RepOD), rekordach GeoNetwork (ISO 19139 i ISO 19115-3) oraz w rekordzie DataCite numeru DOI.`,
  'licence.checks.li1': `Każde stwierdzenie jest klasyfikowane przez porównanie jego tekstu i odnośnika z listą licencji SPDX: jeden identyfikator SPDX albo „nie rozpoznano — sprawdź ręcznie”.`,
  'licence.checks.li2': `Źródła porównuje się po podanych identyfikatorach. Rekord Zenodo i jego rekord DataCite, rekord PANGAEA i jego rekord DataCite oraz zbiór Dataverse i jego rekord DataCite to jeden depozyt i liczą się raz.`,
  'licence.checks.li3': `Zgłaszane sprzeczności: różne licencje w różnych źródłach, tekst i odnośnik, które się różnią, tekst dodający warunki do standardowej licencji oraz ograniczenia dostępu w rekordzie ISO obok otwartej licencji. Pusty rekord DataCite obok licencji podanej gdzie indziej nie jest sprzecznością: ma osobną linijkę.`,
  'licence.checks.li4': `Nie interpretuje skutków prawnych licencji, nie czyta tekstów licencji i nie patrzy na same dane.`,
  'index.atlas.lead': `Część Abyssal Claims:`,

  'footer.source': `Kod źródłowy (AGPL-3.0-or-later)`,
  'footer.cookies': `Ustawienia cookies`,

