  'check.intro': `Dodaj pliki albo wklej link. Narzędzie proponuje, jak je odczytać, Ty potwierdzasz.`,
  'check.busy': `Sprawdzam…`,
  'check.error': `Nie udało się dokończyć sprawdzania.`,

