  'mode.browser.text': `Pliki pobiera Twoja własna przeglądarka. Niektóre serwery danych na to nie pozwalają — wtedy pobierz plik samodzielnie i upuść go tutaj.`,
  'mode.server.label': `Przez serwer Abyssal Claims`,
  'mode.server.text': `Nasz serwer pobiera za Ciebie publiczne pliki ze znanych serwerów danych i niczego nie przechowuje.`,
  'mode.local': `Pliki, które tu upuścisz, nigdy nie opuszczają Twojego komputera — w żadnym z trybów.`,

