  'blocked.switch': `Przełącz na tryb serwera`,
  'blocked.switched': `Wybrano tryb serwera. Kliknij „Sprawdź” ponownie, aby spróbować jeszcze raz.`,
  'blocked.drop': `Albo pobierz plik samodzielnie i upuść go tutaj.`,
  'confirm.title': `Potwierdź, jak odczytać Twoje pliki`,
  'confirm.intro': `Narzędzie proponuje, jak odczytać każdy plik. Sprawdź układ tabeli i znaczenie każdej kolumny i popraw to, co jest błędne. Nic nie jest sprawdzane, dopóki nie potwierdzisz.`,
  'confirm.file': `Plik: {name}`,
  'confirm.encoding': `Kodowanie tekstu: {encoding}`,
  'confirm.submit': `Potwierdź i sprawdź`,
  'confirm.problems': `Tych plików nie udało się odczytać:`,
  'confirm.metadataFiles': `Pliki metadanych, dołączone do danych: {names}`,
  'confirm.notRead': `Nieodczytane, nie zawierają tabeli: {names}`,
  'confirm.checking': `Sprawdzam…`,
  'confirm.singleCruise': `Wszystkie pomiary w tych plikach pochodzą z jednego rejsu jednego statku`,
  'confirm.singleCruise.help': `Zaznacz, jeśli tak: narzędzie sprawdzi wtedy, czy statek mógł w zapisanym czasie przepłynąć z jednej stacji do następnej. Nie zaznaczaj, jeśli w danych są też łodzie lub inne jednostki pracujące równolegle.`,
  'confirm.singleCruise.byColumn': `Kolumna oznaczona jako rejs ma pierwszeństwo przed tym polem w plikach: {names}. Te pliki są sprawdzane rejs po rejsie.`,
  'confirm.mappingFiles': `Plik towarzyszący z mapowaniem (to nie tabela danych), odczytano z niego ustawienia: {names}`,
  'layout.title': `Układ tabeli`,
  'layout.one': `Arkusz „{sheet}” to jedna tabela: jeden wiersz na próbkę, jedna kolumna na zmienną.`,
  'layout.long': `Arkusz „{sheet}” ma format długi: jeden wiersz na pomiar. Nazwy parametrów są w kolumnie „{param}”, wartości w kolumnie „{value}”, jednostki w kolumnie „{unit}”. Narzędzie zamienia to na jeden wiersz na próbkę.`,
  'layout.join': `Pomiary z arkusza „{left}” są łączone z arkuszem „{right}” (pozycje, daty) tam, gdzie kolumna „{leftKey}” jest równa kolumnie „{rightKey}”.`,
  'layout.unsupported': `Tego układu nie da się odczytać: {reason}. Plik zostanie zgłoszony, a pozostałe tabele w nim nadal są sprawdzane.`,
  'layout.change': `Zmień`,
  'layout.hide': `Ukryj`,
  'layout.key.left': `Kolumna klucza w „{sheet}”`,
  'layout.key.right': `Kolumna klucza w „{sheet}”`,
  'layout.long.parameter': `Kolumna z nazwami parametrów`,
  'layout.long.unit': `Kolumna z jednostkami`,
  'layout.long.value': `Kolumna z wartościami`,
  'layout.none': `(brak)`,
  'mapping.title': `Kolumny arkusza „{sheet}”`,
  'mapping.column': `Kolumna`,
  'mapping.unnamed': `Kolumna {n}`,
  'mapping.samples': `Pierwsze wartości`,
