  'convert.companion.help': `Hält Ihre Entscheidungen (vollständige Artenliste, Stationspräfix, WoRMS-Option, NVS-Option) für den nächsten Durchgang fest: legen Sie die Datei zusammen mit den Daten ab.`,
  'convert.doubt.sex-marker': `am Ende steht eine Geschlechtsangabe`,
  'convert.taxa.label': `Vorgeschlagene Taxon-Spalten`,
  'convert.medium.none': `— auswählen —`,
  'convert.sex.none': `—`,
  'convert.taxa.title': `{n} {+n:Spalte|Spalten} als Taxa vorgeschlagen`,
  'convert.taxa.intro': `Das Werkzeug hat diese Spalten vorgeschlagen, weil sie Zahlen unter einem unbekannten Namen enthalten, nicht weil es eine Art erkannt hätte. Eine Spalte wird erst nach Ihrer Bestätigung umgewandelt; entfernen Sie das Häkchen bei jeder, die kein Taxon ist.`,
  'convert.taxa.confirmAll': `Alle gezeigten bestätigen ({n})`,
  'convert.taxa.confirm': `Als Taxon bestätigen: {header}`,
  'convert.taxa.unconfirmed': `{n} vorgeschlagene {+n:Taxon-Spalte ist|Taxon-Spalten sind} nicht bestätigt und {+n:wird|werden} nicht umgewandelt.`,
