  'convert.doubt.slash': `er enthält einen Schrägstrich (zwei Namen?)`,
  'convert.doubt.question': `er enthält ein Fragezeichen`,
  'convert.doubt.stage-range': `er sieht wie ein Stadienbereich aus`,
  'convert.doubt.single-letter': `er enthält einen einzelnen Buchstaben`,
  'convert.doubt.long': `er hat mehr als drei Wörter`,
  'convert.doubt.remark': `nach dem Komma bleibt eine Bemerkung, die weder Stadium noch Zusatz noch Geschlecht ist`,
