  'convert.splits.title': `Namen mit Zusatz, Stadium oder Geschlecht`,
  'convert.splits.intro': `Jeder Name unten wurde in einen wissenschaftlichen Namen und das Herausgenommene geteilt, oder der verbleibende Name wirkt zweifelhaft. Der genaue Text bleibt immer erhalten. Ändern Sie die Felder, wenn der Vorschlag falsch ist, und bestätigen Sie dann jeden einzeln. Die Schaltfläche für alle gezeigten bestätigt nur Namen ohne Zweifel; ein Name mit Zweifel braucht seine eigene Schaltfläche, nachdem Sie ihn geändert oder so übernommen haben. Ein unbestätigter blockiert die Umwandlung.`,
