  'collection.intro': `Lesen Sie die Metadaten einer ganzen Sammlung und erhalten Sie Zahlen je Problem, einige Beispiele und eine Korrekturliste als CSV-Datei. Es werden nur Metadaten gelesen, nie Datendateien. Eine schnelle Stichprobe ist immer als Stichprobe gekennzeichnet; nichts hier erstellt Ranglisten oder vergleicht Einrichtungen.`,
