  'collection.cross.notDone': `Der Vergleich mit DataCite wurde für {n} {+n:Datensatz|Datensätze} nicht durchgeführt (DataCite antwortete nicht); {+n:er wurde|sie wurden} nur anhand {+n:seines|ihres} Katalogeintrags geprüft, und aus dem fehlenden Vergleich entsteht kein Lizenzbefund.`,
  'collection.duplicates': `{n} {+n:Wiederholung wurde|Wiederholungen wurden} nur einmal gezählt: dieselbe DOI mehrfach in der eingefügten Liste oder derselbe Zenodo-Datensatz in mehr als einem Datumsabschnitt.`,
  'collection.checks.title': `Was diese Seite tut`,
