  'collection.checks.li3': `leere Links, eine fehlende Version und eine fehlende räumliche Ausdehnung in den Metadaten.`,
  'collection.checks.li4': `Ein nicht lesbarer Datensatz (nicht erreichbar, von der Quelle zurückgehalten oder in einem nicht unterstützten Profil) wird als nicht gelesen aufgeführt und erhält keinen Befund. Nichts wird gereiht und keine Einrichtungen werden verglichen.`,
