  'licence.intro': `Fügen Sie einen oder mehrere Verweise auf denselben Datensatz ein. Die Seite zeigt, was jede Metadatenquelle zur Lizenz angibt, wie jede Angabe eingeordnet wird und wo sie sich widersprechen.`,
  'licence.input.label': `Verweise auf denselben Datensatz, einer pro Zeile`,
  'licence.input.placeholder': `https://doi.org/10.5281/zenodo.…
https://zenodo.org/records/…`,
  'licence.input.hint': `Eine DOI, ein Zenodo-Record-Link, ein PANGAEA-Link, ein Dataverse-Datensatz-Link (RepOD) oder ein GeoNetwork-Record-Link. Mehrere Zeilen bedeuten mehrere Orte, an denen derselbe Datensatz beschrieben ist.`,
  'licence.submit': `Lizenzen vergleichen`,
  'licence.empty': `Fügen Sie mindestens einen Verweis hinzu.`,
  'licence.busy': `Metadaten werden gelesen…`,
  'licence.sources.title': `Was jede Quelle angibt`,
  'licence.group.shared': `{names}: eine Hinterlegung, beschrieben vom selben Repositorium. Ihre Übereinstimmung bestätigt nichts.`,
  'licence.field': `Feld`,
