  'licence.class': `Eingeordnet als`,
  'licence.class.spdx': `{id} ({name})`,
  'licence.class.unrecognised': `nicht erkannt — von Hand prüfen`,
  'licence.class.missing': `fehlt (die Quelle wurde gelesen und gibt keine Lizenz an)`,
  'licence.class.unreadable': `konnte nicht gelesen werden`,
  'licence.reason.unrecognised': `Das ist weder eine DOI noch ein Zenodo-, PANGAEA- oder Dataverse-Link (RepOD) noch ein GeoNetwork-Record-Link.`,
  'licence.reason.notRead': `Diese Art von Link wird nicht auf Lizenzen gelesen. Fügen Sie stattdessen die DOI des Datensatzes ein, um zu vergleichen, was sein DataCite-Eintrag angibt.`,
  'licence.reason.notReadObis': `Diese Art von Link wird nicht auf Lizenzen gelesen. OBIS-Datensätze haben keine eigene DOI: Wenn derselbe Datensatz auch über GBIF oder das IPT des Datenanbieters veröffentlicht ist und dort eine DOI hat, fügen Sie stattdessen diese DOI ein, um zu vergleichen, was sein DataCite-Eintrag angibt.`,
  'licence.reason.unexpected': `Unerwarteter Fehler: {message}`,
  'licence.reason.http': `Der Eintrag auf {host} konnte nicht geöffnet werden (HTTP {status}); er ist möglicherweise privat oder unveröffentlicht.`,
  'licence.reason.timeout': `{host} hat nicht rechtzeitig geantwortet, daher wurde das Warten beendet. Versuchen Sie es später erneut.`,
  'licence.reason.rateLimit': `{host} hat die Anfrage abgelehnt, weil zu viele Anfragen gestellt wurden. Versuchen Sie es später erneut.`,
  'licence.reason.notDatacite': `DataCite hat keinen Eintrag zu dieser DOI ({host} antwortete „nicht gefunden“). Sie ist möglicherweise bei einer anderen Agentur registriert oder existiert nicht.`,
  'licence.reason.blocked': `Ihr Browser konnte {host} nicht erreichen (der Datenserver verweigert womöglich das direkte Lesen). Wechseln Sie in den Servermodus und vergleichen Sie erneut.`,
  'licence.reason.notAllowed': `Der Host {host} steht nicht auf der Liste der Datenserver dieses Werkzeugs und wurde deshalb nicht kontaktiert.`,
  'licence.switched': `Der Servermodus ist gewählt. Vergleichen Sie erneut, um es noch einmal zu versuchen.`,
  'licence.mode.legend': `Wie die Metadaten-Records abgerufen werden`,
  'licence.mode.browser.text': `Ihr eigener Browser ruft die Metadaten-Records direkt bei den Repositorien ab. Manche Repositorien erlauben das nicht; wechseln Sie dann in den Servermodus.`,
  'licence.mode.server.text': `Unser Server ruft die Metadaten-Records für Sie bei bekannten Repositorien ab und speichert nichts.`,
  'licence.mode.note': `In beiden Modi werden nur Metadaten-Records gelesen. Es werden keine Datendateien heruntergeladen.`,
  'licence.failed.title': `Verweise, die nicht gelesen werden konnten`,
  'licence.summary.title': `Vergleich`,
  'licence.summary.none': `Kein Widerspruch zwischen {n} Quellen mit erkannter Lizenz`,
  'licence.summary.noneMaybeSame': `Kein Widerspruch zwischen {n} Einträgen — aber es sind Zenodo-DOIs, die Versionen einer einzigen Hinterlegung sein können (nicht bestätigt, weil der Zenodo-Eintrag nicht gelesen wurde); dieselbe Quelle kann also doppelt gezählt sein`,
  'licence.summary.single': `Einzelne Quelle — nichts zu vergleichen`,
  'licence.summary.nostated': `Keine Quelle gibt eine Lizenz an — nichts zu vergleichen`,
  'licence.summary.nostatedUnread': `Keine Quelle, die gelesen werden konnte, gibt eine Lizenz an — nichts zu vergleichen`,
  'licence.summary.dataciteSilent': `DataCite gibt keine Lizenz an.`,
  'licence.summary.dataciteSilent.where': `Die Lizenz nennt: {where}.`,
  'licence.summary.dataciteSilent.unread': `Keine gelesene Quelle nennt eine Lizenz, und mindestens eine konnte nicht gelesen werden, also wurde keine Lizenz gefunden.`,
  'licence.summary.dataciteSilent.openaire': `Die OpenAIRE-Richtlinien für Datenarchive machen Rights (die Lizenz) verpflichtend, wenn zutreffend, während DataCite es optional lässt: Fügen Sie die Lizenz im DOI-Record hinzu.`,
  'licence.summary.uncompared': `Angaben gefunden, aber keine ließ sich als eine vom Werkzeug erkannte Lizenz lesen — es wurde nichts verglichen`,
  'licence.summary.partial': `Nur eine Quelle nennt eine vom Werkzeug erkannte Lizenz; die übrigen Angaben ließen sich nicht vergleichen`,
  'licence.summary.contradictions': `Gefundene Widersprüche: {n}`,
  'licence.summary.countOnce': `Quellen einer Hinterlegung zählen einmal.`,
  'licence.summary.unreadable': `Mindestens eine Quelle konnte nicht gelesen werden; sie ist nicht Teil dieses Vergleichs.`,
  'licence.summary.unrecognised': `Als „nicht erkannt“ markierte Angaben lassen sich nicht vergleichen; prüfen Sie sie von Hand.`,
  'licence.attr.title': `Quellenangabe`,
  'licence.attr.note': `Die Quellenangabe ist immer auf Englisch, damit Sie sie unverändert einfügen können. Prüfen Sie sie am Datensatz, bevor Sie sie verwenden.`,
  'licence.attr.copy': `Kopieren`,
  'licence.attr.copied': `In die Zwischenablage kopiert.`,
  'licence.attr.copyFailed': `Kopieren hat hier nicht funktioniert; markieren Sie den Text und kopieren Sie ihn von Hand.`,
  'licence.attr.empty': `Die Quellen enthalten nicht genug für eine Quellenangabe.`,
  'licence.attr.omit.none': `Die Lizenz fehlt in der Angabe: Keine Quelle nennt eine Lizenz, die diese Seite erkennt.`,
  'licence.attr.omit.unreadable': `Die Lizenz fehlt in der Angabe: Mindestens eine Quelle konnte nicht gelesen werden, und keine gelesene nennt eine Lizenz, die diese Seite erkennt.`,
  'licence.attr.omit.several': `Die Lizenz fehlt in der Angabe: In den Quellen wird mehr als eine Lizenz erkannt.`,
  'licence.attr.omit.contradiction': `Die Lizenz fehlt in der Angabe: Die Quellen widersprechen sich.`,
  'licence.attr.omit.unrecognised': `Die Lizenz fehlt in der Angabe: Mindestens eine Angabe wurde nicht erkannt und muss von Hand geprüft werden.`,
  'licence.checks.title': `Was geprüft wird`,
  'licence.checks.p1': `Die Seite liest die Metadaten der Datensätze, auf die Sie verweisen, nie die Datendateien. Sie liest die Lizenzangaben in Zenodo-Records, PANGAEA-Metadaten-Records, Dataverse-Datensätzen (RepOD), GeoNetwork-Records (ISO 19139 und ISO 19115-3) und im DataCite-Record einer DOI.`,
  'licence.checks.li1': `Jede Angabe wird eingeordnet, indem Text und Link mit der SPDX-Lizenzliste verglichen werden: eine SPDX-Kennung oder „nicht erkannt — von Hand prüfen“.`,
  'licence.checks.li2': `Quellen werden anhand der angegebenen Kennungen verglichen. Ein Zenodo-Record und sein DataCite-Record, ein PANGAEA-Record und sein DataCite-Record oder ein Dataverse-Datensatz und sein DataCite-Record sind eine Hinterlegung und zählen einmal.`,
  'licence.checks.li3': `Gemeldete Widersprüche: unterschiedliche Lizenzen in verschiedenen Quellen, Text und Link, die sich unterscheiden, ein Text, der einer Standardlizenz Bedingungen hinzufügt, und Zugangsbeschränkungen in einem ISO-Record neben einer offenen Lizenz. Ein leerer DataCite-Record neben einer anderswo angegebenen Lizenz ist kein Widerspruch: Er hat eine eigene Zeile.`,
  'licence.checks.li4': `Sie deutet die rechtliche Wirkung einer Lizenz nicht, liest keine Lizenztexte und sieht sich die Daten selbst nicht an.`,
