  'blocked.drop': `Oder laden Sie die Datei selbst herunter und ziehen Sie sie hierher.`,
  'confirm.title': `Bestätigen Sie, wie Ihre Dateien gelesen werden`,
  'confirm.intro': `Das Werkzeug schlägt vor, wie jede Datei gelesen wird. Prüfen Sie das Tabellenlayout und die Bedeutung jeder Spalte und ändern Sie, was nicht stimmt. Erst nach Ihrer Bestätigung wird geprüft.`,
