  'confirm.singleCruise': `Alle Messungen in diesen Dateien stammen von einer Fahrt eines Schiffs`,
  'confirm.singleCruise.help': `Setzen Sie das Häkchen, wenn das zutrifft: Das Werkzeug prüft dann, ob das Schiff zwischen aufeinanderfolgenden Stationen hätte fahren können. Kein Häkchen, wenn die Daten auch Boote oder andere gleichzeitig arbeitende Fahrzeuge enthalten.`,
  'confirm.singleCruise.byColumn': `Eine als Fahrt markierte Spalte hat Vorrang vor diesem Häkchen in: {names}. Diese Dateien werden Fahrt für Fahrt geprüft.`,
