  'layout.long': `Blatt „{sheet}“ liegt im Langformat vor: eine Zeile pro Messung. Parameternamen stehen in Spalte „{param}“, Werte in Spalte „{value}“, Einheiten in Spalte „{unit}“. Das Werkzeug macht daraus eine Zeile pro Probe.`,
  'layout.join': `Messungen aus Blatt „{left}“ werden mit Blatt „{right}“ (Positionen, Daten) verknüpft, wo Spalte „{leftKey}“ gleich Spalte „{rightKey}“ ist.`,
