  'convert.worms.finished': `Recherche terminée : {n} {+n:nom|noms} avec réponse.`,
  'convert.worms.stopped': `Recherche interrompue : {done} {+done:nom|noms} sur {total} {+done:a reçu|ont reçu} une réponse. Les autres noms n'ont pas encore d'identifiant ; appuyez de nouveau sur le bouton pour les rechercher, ou continuez sans identifiants.`,
  'convert.worms.error.network': `La recherche n'a pas pu joindre WoRMS (pas de connexion, ou le navigateur a refusé la requête). L'appel échoué n'a rien changé. Vous pouvez réessayer, ou continuer sans identifiants.`,
  'convert.worms.error.http': `WoRMS a répondu par une erreur (HTTP {status}). L'appel échoué n'a rien changé. Vous pouvez réessayer, ou continuer sans identifiants.`,
