  'convert.worms.summary': `Résultats : {exact} {+exact:correspondance exacte retenue|correspondances exactes retenues} automatiquement, {choose} {+choose:nom à choisir par vous|noms à choisir par vous}, {none} {+none:nom sans correspondance|noms sans correspondance}.`,
