  'convert.nerc.title': `Concepts NERC pour les grandeurs mesurées`,
  'convert.nerc.intro': `Chaque colonne de grandeur mesurée est écrite comme une mesure sur chaque événement d'échantillon (sur chaque niveau de profil, pour un fichier de profils), avec son nom et son unité comme dans le tableau des colonnes ci-dessus. Pour une colonne dont vous confirmez le concept, le nom est écrit comme le nom anglais de ce concept (son libellé préféré dans le vocabulaire NERC). Un identifiant du vocabulaire NERC (measurementTypeID pour la grandeur, measurementUnitID pour l'unité) n'est écrit que pour ce que vous confirmez ici, colonne par colonne. Une suggestion est affichée, jamais choisie à votre place.`,
  'convert.nerc.col.unit': `unité`,
  'convert.nerc.col.noUnit': `sans unité`,
  'convert.nerc.type.label': `Concept (measurementTypeID)`,
  'convert.nerc.unit.label': `Unité (measurementUnitID)`,
  'convert.nerc.type.aria': `Concept pour {header}`,
  'convert.nerc.unit.aria': `Unité pour {header}`,
  'convert.nerc.choice.none': `Sans identifiant`,
  'convert.nerc.group.suggested': `Suggestion (concept général vérifié)`,
  'convert.nerc.group.suggestedUnit': `Suggestion (unité vérifiée)`,
  'convert.nerc.group.offered': `Au choix (indique une méthode, une phase ou une grandeur plus étroite)`,
  'convert.nerc.group.nvs': `Résultats de votre recherche NVS`,
  'convert.nerc.group.declared': `Déclaré par le fichier (l'outil n'a pas pu le vérifier)`,
  'convert.nerc.declared.label': `déclaré dans l'en-tête, non vérifié`,
  'convert.nerc.deprecated': `obsolète, non sélectionnable`,
  'convert.nerc.dropped': `Le choix précédent a été abandonné : la grandeur ou l'unité de cette colonne a changé, et un identifiant appartient aux deux.`,
  'convert.nerc.useSuggested': `Utiliser les suggestions pour {n} {+n:colonne|colonnes}`,
  'convert.nerc.useSuggested.help': `Confirme, pour les colonnes sans choix, le concept et l'unité suggérés dans leurs listes. Vous pouvez ensuite modifier chacun d'eux.`,
  'convert.nerc.choose.intro': `Pour chaque colonne, choisissez le concept et l'unité, ou laissez « Sans identifiant » : un identifiant que vous n'avez pas choisi n'est pas écrit, et le récapitulatif dit quelles grandeurs et unités n'en ont pas.`,
  'convert.nerc.choose.label': `Choix du concept et de l'unité`,
  'convert.nvs.title': `Rechercher dans le serveur de vocabulaire NERC (facultatif)`,
  'convert.nvs.optin': `Autoriser la recherche d'un concept ou d'une unité dans NVS`,
  'convert.nvs.optin.help': `Désactivé par défaut. Cocher la case n'envoie rien : un mot ne quitte votre ordinateur que lorsque vous le saisissez pour une colonne et appuyez sur « Rechercher dans NVS ».`,
  'convert.nvs.privacy.title': `Ce qui est envoyé, et à qui`,
  'convert.nvs.privacy.sent': `Ce qui est envoyé : uniquement le mot de recherche que vous saisissez, et rien d'autre. Jamais vos données, valeurs, noms de colonnes, noms de fichiers, descriptions ni rien d'autre de ce que vous avez saisi.`,
  'convert.nvs.privacy.to': `À qui : le serveur de vocabulaire NERC (NVS), exploité par le British Oceanographic Data Centre (BODC, centre britannique de données océanographiques) au National Oceanography Centre (NOC), à l'adresse vocab.nerc.ac.uk. Le mot va de votre navigateur directement à ce service, sans passer par le serveur de ce site.`,
  'convert.nvs.privacy.ip': `Le service voit votre adresse IP, comme tout site que vous ouvrez.`,
  'convert.nvs.privacy.button': `Rien n'est envoyé avant que vous appuyiez sur « Rechercher dans NVS ». Sans cet appui, rien ne quitte votre ordinateur, même si la case est cochée ou si un fichier compagnon l'a cochée.`,
  'convert.nvs.word.type': `Rechercher un concept dans NVS`,
