  'convert.prefix.help': `Certains codes d'échantillon se répètent entre stations et ne peuvent donc pas servir d'identifiants tels quels. L'identifiant de station, deux-points et votre code les rendent uniques.`,
  'convert.splits.title': `Noms avec mention, stade ou sexe`,
  'convert.splits.intro': `Chaque nom ci-dessous a été divisé en nom scientifique et en ce qui en a été retiré, ou le nom restant paraît douteux. Le texte exact est toujours conservé. Corrigez les champs si la proposition est fausse, puis validez chacun. Le bouton pour tous ceux affichés ne valide que les noms sans doute ; un nom douteux a son propre bouton, après l'avoir corrigé ou accepté tel quel. Un non validé bloque la conversion.`,
