  'convert.codes.title': `Codes d'échantillon`,
  'convert.codes.text': `La feuille {sheet} du fichier {file} a des lignes sans code d'échantillon. Le code devient l'identifiant de l'échantillon dans l'archive : il doit donc venir de vous, et le convertisseur n'en invente jamais en silence. Il peut proposer des codes une fois : vous téléchargez votre propre feuille avec une nouvelle colonne, vérifiez les codes et rechargez ce fichier.`,
