  'collection.title': `Revue de collection`,
  'collection.docTitle': `Revue de collection : repérer les problèmes de licence et de métadonnées dans tout un dépôt`,
  'collection.intro': `Lisez les métadonnées d’une collection entière et obtenez des nombres par problème, quelques exemples de chacun et une liste de corrections au format CSV. Seules les métadonnées sont lues, jamais les fichiers de données. Un échantillon rapide est toujours signalé comme échantillon ; rien ici ne classe ni ne compare des institutions.`,
  'collection.kind.legend': `Que lire`,
  'collection.kind.dois': `Une liste de DOI`,
  'collection.kind.datacite': `Un dépôt DataCite ou un préfixe DOI`,
