  'collection.dois.label': `DOI, un par ligne ou séparés par des espaces`,
  'collection.dois.placeholder': `10.5281/zenodo.…
https://doi.org/10.…`,
  'collection.dois.hint': `Chaque DOI est recherché chez DataCite par votre navigateur. Les liens doi.org/… et la forme doi:… sont acceptés ; un DOI répété n’est lu qu’une fois.`,
  'collection.dc.by': `Identifier la collection par`,
  'collection.dc.client': `identifiant client DataCite (dépôt)`,
  'collection.dc.prefix': `préfixe DOI`,
  'collection.dc.label': `Identifiant client ou préfixe`,
  'collection.dc.hint': `Votre navigateur demande la liste à DataCite page par page. Un identifiant client ressemble à « organisation.depot », un préfixe à « 10.1234 ».`,
  'collection.zen.label': `Nom de la communauté (comme dans son adresse sur Zenodo)`,
  'collection.zen.hint': `Zenodo accorde à un invité la lecture de 25 notices par requête et 30 requêtes par minute ; les grandes communautés prennent donc du temps. Au-delà de 10 000 notices, la communauté est lue par tranches selon la date de publication.`,
  'collection.csw.label': `Catalogue`,
  'collection.csw.schema': `Format de métadonnées demandé`,
  'collection.csw.note': `Les catalogues sont lus par l’intermédiaire de notre serveur, qui transmet la réponse et ne conserve rien (voir la page de confidentialité). Seuls les catalogues de cette liste peuvent être lus.`,
  'collection.csw.cross': `Comparer aussi avec DataCite`,
  'collection.csw.cross.note': `Pour les notices qui indiquent un DOI, votre navigateur interroge aussi DataCite et compare les licences des deux sources. Cela ajoute jusqu’à une requête par notice de ce type.`,
