  'licence.checks.title': `Ce que cette page vérifie`,
  'licence.checks.p1': `Cette page lit les métadonnées des notices que vous indiquez, jamais les fichiers de données. Elle lit les mentions de licence des notices Zenodo, des notices de métadonnées PANGAEA, des jeux de données Dataverse (RepOD), des notices GeoNetwork (ISO 19139 et ISO 19115-3) et de la notice DataCite d'un DOI.`,
  'licence.checks.li1': `Chaque mention est classée en comparant son texte et son lien à la liste de licences SPDX : un identifiant SPDX, ou « non reconnue — à vérifier à la main ».`,
  'licence.checks.li2': `Les sources sont comparées par les identifiants qu'elles indiquent. Une notice Zenodo et sa notice DataCite, une notice PANGAEA et sa notice DataCite, ou un jeu de données Dataverse et sa notice DataCite, forment un seul dépôt et comptent une fois.`,
  'licence.checks.li3': `Contradictions signalées : licences différentes dans des sources différentes, texte et lien qui divergent, texte qui ajoute des conditions à une licence standard, et restrictions d'accès dans une notice ISO à côté d'une licence ouverte. Une notice DataCite vide à côté d'une licence indiquée ailleurs n'est pas une contradiction : elle a sa propre ligne.`,
  'licence.checks.li4': `Elle n'interprète pas l'effet juridique d'une licence, ne lit pas les textes de licence et n'examine pas les données elles-mêmes.`,
